corrected_code:
const express = require('express');
const { DataSource } = require('typeorm');

const app = express();
const dataSource = new DataSource({
  type: 'postgres',
  url: process.env.COMPLIANCE_DB_URL
});
dataSource.initialize();

app.get('/api/compliance/incidents/search', async (req, res) => {
  const { classification, status } = req.query;

  // Enforce department access restrictions on compliance search
  try {
    const records = await dataSource.query(
      `SELECT id, incident_code, summary, reporter_anonymous, status, created_at
       FROM whistle_blower_reports
       WHERE classification = $1 AND status = $2 AND department_id = $3
       ORDER BY created_at DESC`,
      [classification || 'ETHICS', status || 'OPEN', req.user.department_id]
    );

    return res.json({ count: records.length, reports: records });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to search compliance reports' });
  }
});

module.exports = app;
